<script setup lang="ts">import { computed, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useTemplateStore } from '../../stores/template'; import { useDocumentStore } from '../../stores/document'; import { useNotificationStore } from '../../stores/notification'; import FileDropzone from './FileDropzone.vue'; import UploadProgress from './UploadProgress.vue'; import BaseButton from '../ui/BaseButton.vue'; import BaseAlert from '../ui/BaseAlert.vue'; const templates = useTemplateStore(); const documents = useDocumentStore(); const notice = useNotificationStore(); const router = useRouter(); const step = ref(1); const templateId = ref(''); const file = ref<File>(); const error = ref(''); const progress = ref(0); const sending = ref(false); const canContinue = computed(() => step.value === 1 ? !!templateId.value : !!file.value)
const selectableTemplates = computed(() => templates.templates.filter((template) => template.status !== 'inativo'))
templates.list().catch(() => { error.value = 'Não foi possível carregar os templates.' }); function selectFile(value: File) { file.value = value; error.value = '' } async function send() { if (!file.value || !templateId.value) return; sending.value = true; try { const result = await documents.upload(file.value, templateId.value, (value) => progress.value = value); notice.push({ type: 'success', message: 'Documento enviado com sucesso.' }); router.push(`/documentos/${result.id}`) } catch (e: any) { error.value = e.response?.data?.error || 'Falha ao enviar o documento.' } finally { sending.value = false } } </script>
<template><div class="card max-w-2xl"><div class="mb-8 flex items-center justify-between"><div v-for="item in [1, 2, 3]" :key="item" class="flex items-center gap-2 text-sm" :class="step >= item ? 'font-semibold text-primary' : 'text-slate-400'"><span class="flex h-8 w-8 items-center justify-center rounded-full border" :class="step >= item ? 'border-primary bg-primary text-white' : 'border-slate-300'">{{ item }}</span><span class="hidden sm:inline">{{ ['Template', 'Arquivo', 'Confirmar'][item - 1] }}</span></div></div><BaseAlert v-if="error" type="error" :message="error" class="mb-4" /><div v-if="step === 1" class="space-y-4"><h2 class="text-lg font-bold">Escolha um template</h2><select v-model="templateId" class="w-full rounded-lg border border-slate-300 px-3 py-2" aria-label="Template"><option value="">Selecione…</option><option v-for="template in selectableTemplates" :key="template.id" :value="template.id">{{ template.nome }} · {{ template.status === 'ativo' ? `v${template.versaoAtual}` : 'rascunho' }}</option></select><p v-if="!templates.loading && !selectableTemplates.length" class="text-sm text-amber-700">Nenhum template disponível. Crie ou gere um em Templates.</p></div><div v-else-if="step === 2" class="space-y-4"><h2 class="text-lg font-bold">Selecione o arquivo</h2><FileDropzone @select="selectFile" @error="error = $event" /><p v-if="file" class="text-sm text-green-700">Selecionado: {{ file.name }}</p></div><div v-else class="space-y-4"><h2 class="text-lg font-bold">Confirme o envio</h2><dl class="rounded-lg bg-slate-50 p-4 text-sm"><div class="flex justify-between"><dt>Template</dt><dd class="font-semibold">{{ templates.templates.find((t) => t.id === templateId)?.nome }}</dd></div><div class="mt-2 flex justify-between"><dt>Arquivo</dt><dd class="font-semibold">{{ file?.name }}</dd></div></dl><UploadProgress v-if="sending" :progress="progress" /></div><div class="mt-8 flex justify-between"><BaseButton v-if="step > 1" variant="secondary" @click="step--">Voltar</BaseButton><span v-else /><BaseButton v-if="step < 3" :disabled="!canContinue" @click="step++">Continuar</BaseButton><BaseButton v-else :loading="sending" @click="send">Enviar documento</BaseButton></div></div></template>
